export const shapeTypes=[['rectangle','Rectangle'],['ellipse','Ellipse'],['triangle','Triangle'],['diamond','Diamond'],['star','Star'],['custom','Custom']];
const safe=value=>/^#[\da-f]{6}$/i.test(value||'')?value:'#292536';
export function shapeSettings(values={}){return {shape:shapeTypes.some(([id])=>id===values.shape)?values.shape:'rectangle',color:safe(values.color),fill:/^#[\da-f]{6}$/i.test(values.fill||'')?values.fill:'#ffffff',stroke:Math.max(1,Math.min(20,Number(values.stroke)||2.5)),fillOpacity:Math.max(0,Math.min(100,Number.isFinite(Number(values.fillOpacity))?Number(values.fillOpacity):15))};}
export function customShapeObject(raw,values={}){if(raw.length<3)throw new Error('Draw a larger custom shape.');const s=shapeSettings({...values,shape:'custom'}),pad=s.stroke*2,minX=Math.min(...raw.map(p=>p.x)),minY=Math.min(...raw.map(p=>p.y)),maxX=Math.max(...raw.map(p=>p.x)),maxY=Math.max(...raw.map(p=>p.y)),w=Math.max(12,maxX-minX+pad*2),h=Math.max(12,maxY-minY+pad*2);return {type:'shape',x:minX-pad,y:minY-pad,w,h,baseW:w,baseH:h,points:raw.map(p=>({x:p.x-minX+pad,y:p.y-minY+pad})),...s};}
export function shapeObject(start,end,values={}){const s=shapeSettings(values),x=Math.min(start.x,end.x),y=Math.min(start.y,end.y),w=Math.max(24,Math.abs(end.x-start.x)),h=Math.max(24,Math.abs(end.y-start.y)),object={type:'shape',x,y,w,h,baseW:w,baseH:h,...s},template=values.customShape,points=values.points||template?.points;if(s.shape==='custom'&&Array.isArray(points)&&points.length>=3){object.points=points.map(point=>({x:Number(point.x)||0,y:Number(point.y)||0}));object.baseW=Math.max(1,Number(values.baseW)||1);object.baseH=Math.max(1,Number(values.baseH)||1);const templateId=values.templateId||template?.id;if(typeof templateId==='string')object.templateId=templateId;}return object;}
export function shapePath(object){const w=object.w,h=object.h,p=object.shape;if(p==='ellipse')return `<ellipse cx="${w/2}" cy="${h/2}" rx="${Math.max(1,w/2-object.stroke)}" ry="${Math.max(1,h/2-object.stroke)}"/>`;if(p==='triangle')return `<path d="M ${w/2} ${object.stroke} L ${w-object.stroke} ${h-object.stroke} L ${object.stroke} ${h-object.stroke} Z"/>`;if(p==='diamond')return `<path d="M ${w/2} ${object.stroke} L ${w-object.stroke} ${h/2} L ${w/2} ${h-object.stroke} L ${object.stroke} ${h/2} Z"/>`;if(p==='star'){const points=Array.from({length:10},(_,i)=>{const a=-Math.PI/2+i*Math.PI/5,r=(i%2?w*.2:w*.46),ry=(i%2?h*.2:h*.46);return `${w/2+Math.cos(a)*r},${h/2+Math.sin(a)*ry}`}).join(' ');return `<polygon points="${points}"/>`;}if(p==='custom'){const points=(object.points||[]).map(pt=>`${pt.x*w/(object.baseW||w)},${pt.y*h/(object.baseH||h)}`).join(' ');return `<polygon points="${points}"/>`;}return `<rect x="${object.stroke/2}" y="${object.stroke/2}" width="${Math.max(1,w-object.stroke)}" height="${Math.max(1,h-object.stroke)}" rx="${Math.min(12,w/8,h/8)}"/>`;}
export function shapeMarkup(object,hitWidth=0){const s=shapeSettings(object),path=shapePath({...object,...s});return `<g fill="${s.fill}" fill-opacity="${s.fillOpacity/100}" stroke="${s.color}" stroke-width="${s.stroke}" stroke-linejoin="round">${path}</g>${hitWidth?`<g class="vector-hit" fill="transparent" stroke="transparent" stroke-width="${hitWidth}">${path}</g>`:''}`;}
const html=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const templatePreview=template=>template.points.map(point=>`${4+point.x*52},${4+point.y*36}`).join(' ');
export function shapeControls(values,disabled=false,library=[],options={}){const s=shapeSettings(values),off=disabled?'disabled':'',active=options.activeId||'';return `<div class="shape-settings"><div class="draw-label">Shape</div><div class="shape-grid" role="group" aria-label="Shape type">${shapeTypes.filter(([id])=>id!=='custom').map(([id,name])=>`<button class="shape-option ${s.shape===id&&!active?'chosen':''}" data-shape="${id}" aria-pressed="${s.shape===id&&!active}" ${off}><span class="shape-glyph shape-${id}"></span><span>${name}</span></button>`).join('')}<button class="shape-option ${s.shape==='custom'&&!active?'chosen':''}" data-draw-custom aria-pressed="${s.shape==='custom'&&!active}" ${off}><span class="shape-glyph shape-custom"></span><span>Draw new</span></button></div><div class="shape-library-head"><div><b>My Shapes</b><small>Saved on this device</small></div><button data-save-custom ${!options.canSave||disabled?'disabled':''}>Save selected</button></div>${library.length?`<div class="shape-library" role="list" aria-label="Saved custom shapes">${library.map(template=>`<div class="shape-template ${active===template.id?'chosen':''}" role="listitem"><button class="shape-template-use" data-saved-shape="${html(template.id)}" title="Use ${html(template.name)}" ${off}><svg viewBox="0 0 60 44" aria-hidden="true"><polygon points="${templatePreview(template)}"></polygon></svg><span>${html(template.name)}</span></button><div class="shape-template-actions"><button data-shape-library-action="rename" data-shape-id="${html(template.id)}" aria-label="Rename ${html(template.name)}" title="Rename">✎</button><button data-shape-library-action="delete" data-shape-id="${html(template.id)}" aria-label="Delete ${html(template.name)}" title="Delete">×</button></div></div>`).join('')}</div>`:'<p class="shape-library-empty">Select a custom shape, then save it here to stamp it again at any size.</p>'}<div class="property-row"><label>Outline</label><input data-shape-prop="color" type="color" value="${s.color}" ${off}></div><div class="property-row"><label>Fill</label><input data-shape-prop="fill" type="color" value="${s.fill}" ${off}></div><div class="draw-range"><label>Fill opacity</label><output id="shape-opacity-value">${s.fillOpacity}%</output><input data-shape-prop="fillOpacity" type="range" min="0" max="100" step="1" value="${s.fillOpacity}" ${off}></div><div class="draw-range"><label>Outline width</label><output id="shape-width-value">${s.stroke} px</output><input data-shape-prop="stroke" type="range" min="1" max="20" step=".5" value="${s.stroke}" ${off}></div><p class="draw-description">Draw a new silhouette, or choose a saved shape and drag to stamp it. Hold Alt while moving objects to bypass snapping.</p></div>`;}
